// Pre-recorded character voices (Kokoro TTS, generated by tools/make-voices.mjs).
// A line's file name is a hash of voice + spoken text, so the game and the generator always agree.
import { plain } from './text.js';

export function spoken(text) {
  return plain(text)
    .replace(/22:40/g, 'ten forty').replace(/22:30/g, 'ten thirty').replace(/23:00/g, 'eleven')
    .replace(/\bO\. Blackwood/g, 'O Blackwood').replace(/Aurora-7/g, 'Aurora Seven').replace(/\bARIA\b/g, 'Aria').replace(/_{2,}/g, '…').replace(/—/g, ',').replace(/\.\.\./g, '…').replace(/\s+/g, ' ').trim();
}
export function voiceKey(voice, text) {
  const s = voice + '|' + spoken(text);
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0');
}

const BASE = new URL('../../assets/voice/', import.meta.url).href;
let current = null;
export const voiceState = { on: true, volume: 1 };

// play a line; resolves with its duration in seconds (0 if there is no file or voice is off)
export function playLine(voice, text, onEnd) {
  stopLine();
  if (!voice || !voiceState.on) return Promise.resolve(0);
  const a = new Audio(BASE + voiceKey(voice, text) + '.mp3');
  a.volume = voiceState.volume; current = a;
  return new Promise(res => {
    let done = false;
    const fin = d => { if (!done) { done = true; res(d); } };
    a.addEventListener('loadedmetadata', () => fin(a.duration || 0), { once: true });
    a.addEventListener('error', () => fin(0), { once: true });
    a.addEventListener('ended', () => { if (current === a) current = null; onEnd?.(); }, { once: true });
    a.play().catch(() => fin(0));
    setTimeout(() => fin(0), 2500);
  });
}
export function stopLine() { if (current) { current.pause(); current = null; } }
export const isPlaying = () => !!current && !current.paused;
